func (s *Server) handlePageIndexGET(w http.ResponseWriter, r *http.Request) {
	sess, _, ok := s.auth(w, r)
	if !ok {
		return
	}

	if r.URL.Path != "/" {
		s.render404(w, r)
		return
	}

	q := r.URL.Query()
	var query app.SearchParams
	query.Term = q.Get("q")
	pageCache := newPageCache(s, r, nil)

	p := app.PageIndex{
		App: s.app,
		Base: app.Base{
			App: s.app,
		},
	}
	body, err := p.GET(r, sess, pageCache, query)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageIndex.GET", err)
		return
	}
	genericHead := s.app.Head(r)

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)

		_, _ = io.WriteString(w, `data-signals:q="'`)
		writeSignalString(w, query.Term)
		_, _ = io.WriteString(w, `'"`)
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, `data-effect="const params = new URLSearchParams();
			if ($q) params.set('q', $q);
			const query = params.toString();
			window.history.replaceState(null, '', query ? '/?' + query : '/');
		"`)
	}

	if err := s.writeHTML(
		w, r, sess, genericHead, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.logErr("rendering PageIndex", err)
		return
	}
	_ = pageCache.writeBake(w)
}

func (s *Server) handlePageIndexPOSTSearch(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	// CSRF protection covers every state-changing action, including
	// the ones that read nothing of the session.
	if _, _, ok := s.auth(w, r); !ok {
		return
	}
	var signals app.SearchParams
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}

	sse := datastar.NewSSE(w, r, datastar.WithCompression())
	p := app.PageIndex{
		App: s.app,
		Base: app.Base{
			App: s.app,
		},
	}
	err := p.POSTSearch(r, newSSE(sse), signals)
	if err != nil {
		s.httpErrIntern(w, r, sse, "handling action PageIndex.Search", err)
		return
	}
}

